    h,w=len(grid),len(grid[0])
    rows=[]
    for r,row in enumerate(grid):
        if len(set(row))==1 or (len(set(row))==2 and sum(v not in (5,9) for v in row)>=2):
            rows.append(r)
    cols=[]
    for c in range(w):
        vals=[grid[r][c] for r in range(h)]
